    racional: 'O elranatamabe é um anticorpo bispecífico: ao ligar-se ao CD3 dos linfócitos T e ao BCMA das células do mieloma, provoca citotoxicidade mediada por células T dirigida ao tumor. A parte 1 caracteriza segurança e tolerabilidade e define as doses ótimas da combinação. A parte 2 compara a taxa de resposta completa com doença residual mensurável negativa e a sobrevida livre de progressão entre os dois esquemas, em pacientes com mieloma recém-diagnosticado.',
