      'Parte 1: mieloma recidivado ou refratário com 1 a 2 linhas prévias incluindo pelo menos um imunomodulador e um inibidor de proteassoma; ou mieloma recém-diagnosticado inelegível a transplante por idade de 65 anos ou mais, ou abaixo de 65 anos com comorbidades que inviabilizem o transplante',
